#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int m=3*n;
        vector<long long>a(m);
        for(int i=0;i<m;i++){
            cin>>a[i];
        }
        sort(a.rbegin(),a.rend());
        vector<long long> prefix(m+1,0);
        for(int i=0;i<m;i++){
            prefix[i+1]=prefix[i]+a[i];
        }
        long long answer=0;
        for(int A=0;A<=n;A++){
            int left=0;
            int right=n-A;
            auto value =[&](int B)->long long {
                int first=A;
                int second =A+2*B;
                int third=3*n-2*A-B;
                return 2LL*prefix[first]+prefix[second]+3LL*prefix[third];
                
            };
            while(right-left>5){
                int mid1=left+(right-left)/3;
                int mid2=right-(right-left)/3;
                if(value(mid1)<value(mid2))
                    left=mid1+1;
                else
                    right=mid2-1;
            }
            for(int B=left;B<=right;B++){
                answer=max(answer,value(B));
            }
        }
        cout<<answer<<'\n';
    }
}
